#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_N 105
#define MAX_QUEUE 10000

int queue_x[MAX_QUEUE], queue_y[MAX_QUEUE];
int dist[MAX_N][MAX_N];
int visited[MAX_N][MAX_N];

int minimumStepsToExit(int n, int m, int maze[MAX_N][MAX_N], int startX, int startY, int endX, int endY) {
    if (startX == endX && startY == endY) {
        return 0;
    }

    if (maze[startX][startY] == 0 || maze[endX][endY] == 0) {
        return -1;
    }

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            dist[i][j] = -1;
            visited[i][j] = 0;
        }
    }

    int front = 0, rear = 0;
    queue_x[rear] = startX;
    queue_y[rear] = startY;
    rear++;
    dist[startX][startY] = 0;
    visited[startX][startY] = 1;

    while (front < rear) {
        int cur_x = queue_x[front];
        int cur_y = queue_y[front];
        front++;

        int step = maze[cur_x][cur_y];

        for (int d = 0; d < 4; d++) {
            int nx = cur_x + dx[d] * step;
            int ny = cur_y + dy[d] * step;

            if (nx >= 0 && nx < n && ny >= 0 && ny < m && 
                maze[nx][ny] != 0 && !visited[nx][ny]) {
                visited[nx][ny] = 1;
                dist[nx][ny] = dist[cur_x][cur_y] + 1;

                if (nx == endX && ny == endY) {
                    return dist[nx][ny];
                }

                queue_x[rear] = nx;
                queue_y[rear] = ny;
                rear++;
            }
        }
    }

    return -1;
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) {
        return 1;
    }

    if (n <= 0 || m <= 0) {
        printf("-1\n");
        return 0;
    }

    int maze[MAX_N][MAX_N];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (scanf("%d", &maze[i][j]) != 1) {
                return 1;
            }
        }
    }

    int startX, startY, endX, endY;
    if (scanf("%d %d %d %d", &startX, &startY, &endX, &endY) != 4) {
        return 1;
    }

    if (startX < 0 || startX >= n || startY < 0 || startY >= m ||
        endX < 0 || endX >= n || endY < 0 || endY >= m) {
        printf("-1\n");
        return 0;
    }

    int result = minimumStepsToExit(n, m, maze, startX, startY, endX, endY);
    printf("%d\n", result);

    return 0;
}
